WITH remaining_keys AS (SELECT promo_code FROM promotions EXCEPT ALL SELECT promo_code FROM promotions WHERE discount_pct >= 0.21), verified AS (SELECT s.* FROM promotions s INNER JOIN remaining_keys k ON s.promo_code = k.promo_code) SELECT DATE_TRUNC('MONTH', ends_on) AS activity_month, CASE WHEN discount_pct >= 0.27 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, SUM(CASE WHEN promo_code = 'BUNDLE' THEN discount_pct ELSE 0 END) AS bundle_discount_pct, COUNT(CASE WHEN channel = 'mobile' THEN 1 END) AS mobile_count, PERCENTILE_APPROX(discount_pct, ARRAY(0.25, 0.5, 0.75)) AS discount_pct_quartiles FROM verified GROUP BY DATE_TRUNC('MONTH', ends_on), CASE WHEN discount_pct >= 0.27 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY activity_month DESC;
